import styled from '@emotion/styled';
import { composeStyles } from 'utils/emotion';

type TimePeriodSelectorVariant = 'default' | 'modal';

type SelectorVariantProps = {
  $variant?: TimePeriodSelectorVariant;
};

type BooleanVariantProps = {
  $active?: boolean;
  $muted?: boolean;
  $dimmed?: boolean;
};

export const Panel = styled.div<SelectorVariantProps>(
  composeStyles<SelectorVariantProps>(
    {
      display: 'flex',
      flexDirection: 'column',
      alignItems: 'flex-start',
    },
    {
      $variant: {
        default: {
          width: '540px',
          background: '#ffffff',
          border: '1px solid rgba(0, 0, 0, 0.08)',
          borderRadius: '12px',
          boxShadow: '0px 0px 4px rgba(85, 73, 52, 0.24)',
        },
        modal: {
          width: '705px',
          background: 'transparent',
          border: 'none',
          borderRadius: '0px',
          boxShadow: 'none',
        },
      },
    },
  ),
);

export const ChipAbbreviation = styled.span({
  color: 'var(--color-fg-secondary, #67665F)',
  fontFamily: "var(--font-family-body, 'Work Sans', sans-serif)",
  fontWeight: '400',
