  fontSize: '14px',
  lineHeight: '140%',
  letterSpacing: '0',
});

export const PanelBody = styled.div<SelectorVariantProps>(
  composeStyles<SelectorVariantProps>(
    {
      display: 'flex',
      flexDirection: 'column',
      alignItems: 'flex-start',
      gap: '32px',
      padding: '24px',
      width: '100%',
    },
    {
      $variant: {
        default: {
          padding: '24px',
          width: '100%',
        },
        modal: {
          padding: '0px',
          width: 'auto',
        },
      },
    },
  ),
);

export const TimeRangeSection = styled.div({
  display: 'flex',
  flexDirection: 'column',
  alignItems: 'flex-start',
  gap: '16px',
  width: '100%',
});

export const RangeHeader = styled.div({
  display: 'flex',
  flexDirection: 'row',
  alignItems: 'center',
  gap: '8px',
});

export const RangeLabelText = styled.span({
  fontFamily: "'Work Sans', sans-serif",
  fontStyle: 'normal',
  fontWeight: '400',
  fontSize: '14px',
  lineHeight: '140%',
  textAlign: 'center',
  color: '#141414',
});

export const PeriodValueGroup = styled.div({
  display: 'flex',
  flexDirection: 'row',
  alignItems: 'center',
  gap: '4px',
});

export const RangeHeadlineText = styled.span({
  fontFamily: "'Work Sans', sans-serif",
  fontStyle: 'normal',
  fontWeight: '600',
  fontSize: '14px',
  lineHeight: '140%',
  color: '#0D0D0C',
});

export const RangeSublineText = styled.span({
  fontFamily: "'Work Sans', sans-serif",
  fontStyle: 'normal',
  fontWeight: '400',
  fontSize: '12px',
  lineHeight: '140%',
  color: '#67665F',
});

export const SliderAreaContainer = styled.div({
  display: 'flex',
  flexDirection: 'column',
  alignItems: 'flex-start',
  gap: '4px',
  width: '100%',
