export const SliderTrackWrapper = styled.div<SliderTrackWrapperProps>(
  composeStyles<SliderTrackWrapperProps>(
    {
      display: 'flex',
      flexDirection: 'row',
      alignItems: 'center',
      padding: '4px 0px',
      width: '100%',
      height: '16px',
      cursor: 'pointer',
    },
    {
      $noDrag: {
        true: { cursor: 'default' },
      },
    },
  ),
);

export const SliderTrack = styled.div({
  position: 'relative',
  display: 'flex',
  flexDirection: 'column',
  alignItems: 'flex-start',
  isolation: 'isolate',
  width: '100%',
  height: '8px',
  background: 'rgba(20, 20, 20, 0.08)',
  borderRadius: '16px',
  overflow: 'visible',
  flexGrow: '1',
});

export const SliderAvailableZone = styled.div({
  position: 'absolute',
  top: '0',
  left: '0',
  height: '8px',
  background: '#50A5E2',
  opacity: '0.48',
  borderRadius: '512px',
  pointerEvents: 'none',
