export const SliderProgressBar = styled.div({
  position: 'absolute',
  top: '0',
  height: '8px',
  background: '#3598DE',
  borderRadius: '512px',
  transition: 'left 60ms ease, width 60ms ease',
  pointerEvents: 'none',
});

export const SliderHandlePoint = styled.div({
  position: 'absolute',
  top: '50%',
  width: '20px',
  height: '20px',
  borderRadius: '50%',
  background: '#3598DE',
  border: '2px solid #FFFFFF',
  boxShadow: '0px 0px 8px rgba(0, 0, 0, 0.16)',
  transform: 'translate(-50%, -50%)',
  zIndex: '3',
  pointerEvents: 'none',
